$hal = max(1, (int) ($_GET['hal'] ?? 1));
$per = 20;
$offset = ($hal - 1) * $per;
$jumlah = $pdo->query('SELECT COUNT(*) FROM produk')->fetchColumn();
$st = $pdo->prepare('SELECT * FROM produk ORDER BY id LIMIT :m OFFSET :o');
$st->bindValue(':m', $per, PDO::PARAM_INT);
$st->bindValue(':o', $offset, PDO::PARAM_INT);
$st->execute();
